import{_ as a,o,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Cooking","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/cooking.md","filePath":"es/guide/professions/cooking.md"}'),r={name:"es/guide/professions/cooking.md"};function s(t,e,c,l,d,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="cooking" tabindex="-1">Cooking <a class="header-anchor" href="#cooking" aria-label="Enlace permanente a &quot;Cooking&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Esta página describe el rediseño previsto, no mecánicas confirmadas en el juego. <strong>Implementación/disponibilidad:</strong> no establecida para este rediseño. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-08 frente a la <a href="/Syrolands-Public/es/game-design/professions/cooking.html">especificación completa del diseño</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Cooking se propone como preparación interactiva en un puesto de cocina real.</li><li>La comida favorece supervivencia, bienestar y recuperación, en lugar de ofrecer mejoras genéricas como las pociones.</li><li>Importan los tiempos, los ingredientes y las recetas aprendidas; los efectos nutricionales exactos siguen abiertos.</li></ul><h2 id="what-it-does" tabindex="-1">Qué hace <a class="header-anchor" href="#what-it-does" aria-label="Enlace permanente a &quot;Qué hace&quot;">​</a></h2><p>Cooking se concibe como trabajo manual en un puesto real: un gump de Cooking representa una instalación de hoguera, cocina, fogón, horno o parrilla. Los ingredientes empiezan a cocinarse al colocarlos en sus zonas de trabajo; cada alimento tiene distintos intervalos de preparación. Los tiempos y el montaje importan.</p><h2 id="why-take-it-into-the-field" tabindex="-1">¿Por qué llevarlo a una expedición? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Enlace permanente a &quot;¿Por qué llevarlo a una expedición?&quot;">​</a></h2><p>La comida debería contribuir a la saciedad, nutrición, recuperación, eficiencia de stamina, fatiga, resistencia a la temperatura y supervivencia situacional. No debería convertirse en una colección de mejoras de estadísticas similares a pociones. Camping puede proporcionar un puesto de cocina en la naturaleza, mientras que el combustible conecta con Lumberjacking.</p><h2 id="learning-and-specialization" tabindex="-1">Aprendizaje y especialización <a class="header-anchor" href="#learning-and-specialization" aria-label="Enlace permanente a &quot;Aprendizaje y especialización&quot;">​</a></h2><p>Un Culinary Journal reúne recetas y conocimientos alimentarios de culturas, cocineros, libros, exploración y experimentación. Un Taste Codex personal podría revelar preferencias al comer, en lugar de mostrar todos los platos favoritos al crear el personaje. Estos platos pueden aportar más bienestar o satisfacción. Un conocimiento culinario amplio puede seguir siendo una meta del juego avanzado.</p><h2 id="progression-and-related-crafts" tabindex="-1">Progresión y oficios relacionados <a class="header-anchor" href="#progression-and-related-crafts" aria-label="Enlace permanente a &quot;Progresión y oficios relacionados&quot;">​</a></h2><p>Una habilidad baja debería permitir preparar comidas sencillas útiles; una habilidad mayor amplía las tolerancias y mejora el control sin sustituir la ejecución. Se aplican el <a href="/Syrolands-Public/es/guide/professions/overview.html">aprendizaje compartido y la producción por lotes</a>. <a href="/Syrolands-Public/es/guide/professions/lumberjacking.html">Lumberjacking</a> aporta conocimiento sobre combustibles; los efectos exactos de nutrición, gustos y recuperación siguen abiertos.</p><p><a href="/Syrolands-Public/es/guide/professions/overview.html">Todas las profesiones</a> · <a href="/Syrolands-Public/es/game-design/professions/cooking.html">Especificación completa del diseño</a></p>',13)])])}const g=a(r,[["render",s]]);export{m as __pageData,g as default};
